/**
 * Driver pasted directly into Streamlabs' own Alert Box "Custom HTML/CSS/JS"
 * editor, one type/tier/variant combination at a time (generated by
 * control.html's "Streamlabs Alert Box code" section). Streamlabs owns
 * receiving the event, queueing, and duration, and re-renders this HTML
 * fresh for every alert, so this file only renders once, from whatever
 * `{token}` values are already substituted into the DOM, with nothing left
 * running afterward that could need reconnecting.
 *
 * Tier and variant aren't computed here: each generated widget bakes in a
 * fixed `data-tier`/`data-variant`, and Streamlabs' own per-variation
 * condition (not anything in this file) decides which pasted widget fires.
 */
import { AlertStage } from "./components/AlertStage.js";

const DURATION = 5000;
const TOP_OFFSET = 96;

/**
 * The seven per-type Alert Box boxes Streamlabs exposes; `resub` and
 * `giftsub` both map to this repo's single `sub` `AlertType`.
 */
type StreamlabsAlertBoxType =
  "follow" | "sub" | "resub" | "giftsub" | "bits" | "raid" | "tip";

const fmt = (n: number): string =>
  String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",");

/**
 * Trims raw text and rejects anything still shaped like `{token}`: Streamlabs
 * leaves a token's literal placeholder in place when it doesn't apply to
 * this alert type or the platform didn't supply a value, so that shape
 * means absent, not data.
 */
function cleanText(raw: string | null | undefined): string {
  const text = raw?.trim() ?? "";
  return text && !/^\{.*\}$/.test(text) ? text : "";
}

/**
 * Reads one `[data-token]` span's text from `tokens`' own direct children,
 * stripping non-letters before comparing: Streamlabs has been observed
 * inserting invisible characters into the attribute that break exact
 * matching but look identical in a text dump.
 */
function readToken(tokens: Element, name: string): string {
  const el = Array.from(tokens.children).find(
    (child) =>
      (child as HTMLElement).dataset.token?.replace(/[^a-zA-Z]/g, "") === name,
  ) as HTMLElement | undefined;
  return cleanText(el?.textContent);
}

/**
 * Reads `img`/`messageTemplate`/`userMessage` by the specific element id
 * Streamlabs' own default template uses for each: substitution for these
 * three appears to be keyed off the id itself, not simple text matching,
 * confirmed by removing the id from Streamlabs' own template breaking it.
 */
function readRichText(elementId: string): string {
  return cleanText(document.getElementById(elementId)?.textContent);
}

/**
 * The name Streamlabs substitutes into our own standalone `{name}` token,
 * or, if that's empty, whatever name it embedded inside its own rendered
 * `{messageTemplate}` (it wraps an interpolated `{name}` there in its own
 * `data-token="name"` markup for a letter-reveal animation), which testing
 * has shown to arrive even when the standalone token didn't.
 */
function readName(tokens: Element): string {
  const direct = readToken(tokens, "name");
  if (direct) {
    return direct;
  }
  const alertMessage = document.getElementById("alert-message");
  const nested = alertMessage
    ? Array.from(
        alertMessage.querySelectorAll<HTMLElement>("[data-token]"),
      ).find((el) => el.dataset.token?.replace(/[^a-zA-Z]/g, "") === "name")
    : undefined;
  return cleanText(nested?.textContent);
}

function readAvatar(): string | undefined {
  return readRichText("alert-image") || undefined;
}

function parseAmount(raw: string): number {
  const n = parseFloat(raw.replace(/[^0-9.]/g, ""));
  return isNaN(n) ? 0 : n;
}

function buildEvent(
  tokens: Element,
  boxType: StreamlabsAlertBoxType,
  tier: AlertTier,
): AlertStageEvent {
  const name = readName(tokens) || "someone";
  const avatar = readAvatar();
  const message =
    readRichText("alert-user-message") ||
    readToken(tokens, "message") ||
    undefined;
  // Streamlabs only fills this in when the streamer has set a custom
  // "Message Template" for this alert type in their own dashboard (unset
  // otherwise); when set, it's meant to replace the default one-liner
  // below it, that's the whole point of the streamer configuring it.
  const messageTemplate = readRichText("alert-message") || undefined;
  // TEMPORARY: remove once the resub "$" mystery is confirmed.
  console.log("[zw] messageTemplate", {
    boxType,
    messageTemplate,
    alertMessageOuterHTML: document.getElementById("alert-message")?.outerHTML,
  });

  if (boxType === "follow") {
    return {
      type: "follow",
      name,
      avatar,
      detail: messageTemplate || "just followed",
      tier,
    };
  }
  if (boxType === "sub") {
    return {
      type: "sub",
      name,
      avatar,
      message,
      detail: messageTemplate || "1 month",
      amount: "1",
      tier,
    };
  }
  if (boxType === "resub") {
    const rawMonths = readToken(tokens, "months");
    const months = parseAmount(rawMonths) || 1;
    return {
      type: "sub",
      name,
      avatar,
      message,
      headline: "Resub",
      // TEMPORARY: zero-width space escape sequences bracketing the
      // digit, testing whether that breaks whatever external process is
      // prepending "$" to bare numbers in this widget.
      detail: `DEBUG months=\u200b${months}\u200b end`,
      amount: String(months),
      tier,
    };
  }
  if (boxType === "giftsub") {
    // No explicit anonymous/community flag from Streamlabs, so an absent or
    // "anonymous" {name} means an anonymous gifter, and {count} above 1
    // means a community gift rather than one aimed at a specific viewer.
    const rawName = readToken(tokens, "name");
    const isAnonymous = !rawName || /^anonymous$/i.test(rawName);
    const count = parseAmount(readToken(tokens, "count")) || 1;
    const isCommunity = count > 1;
    return {
      type: "sub",
      name: isAnonymous ? "An anonymous gifter" : rawName,
      avatar: isAnonymous ? undefined : avatar,
      headline: isCommunity ? "Community gift" : "Gifted sub",
      detail: isCommunity
        ? `${count} subs gifted to the community`
        : "gifted a sub",
      amount: isCommunity ? `×${count}` : undefined,
      tier,
    };
  }
  if (boxType === "bits") {
    const amount = parseAmount(readToken(tokens, "amount"));
    return {
      type: "bits",
      name,
      avatar,
      message,
      amount: `${fmt(amount)} bits`,
      detail: messageTemplate || "cheered",
      tier,
    };
  }
  if (boxType === "raid") {
    const party = parseAmount(readToken(tokens, "count")) || 1;
    return {
      type: "raid",
      name,
      avatar,
      message,
      party,
      detail:
        messageTemplate ||
        `${party} ${party === 1 ? "mate in tow" : "mates in tow"}`,
      amount: String(party),
      headline: "Incoming raid",
      tier,
    };
  }
  const amount = parseAmount(readToken(tokens, "amount"));
  return {
    type: "tip",
    name,
    avatar,
    message,
    amount: `$${amount}`,
    detail: messageTemplate || "chucked in",
    tier,
  };
}

const AVATAR_LOOKUP_URL =
  "https://zw-twitch-relay.djzwackery.workers.dev/twitch/avatar";

const AVATAR_FETCH_TIMEOUT_MS = 1200;

// Replace with the real token before pasting this into Streamlabs (ask
// whoever deployed the Worker for it, see worker/README.md). This file
// itself, including this literal placeholder, is served publicly from
// djzwackery.com, so the real token can never live here in source, only
// in the copy that actually gets pasted into your Streamlabs dashboard.
const API_TOKEN = "PASTE_YOUR_API_TOKEN_HERE";

/**
 * The relay Worker's `/twitch/avatar` response shape.
 */
interface AvatarLookupResponse {
  /**
   * The resolved avatar URL, or null if the login wasn't found or has no image.
   */
  avatarUrl: string | null;
}

/**
 * Best-effort live lookup for a real Twitch avatar via the relay Worker,
 * since Streamlabs' Alert Box gives no reliable avatar token itself. Uses
 * the resolved display name as the Twitch login, which only matches when
 * the two are identical, not guaranteed for a non-ASCII display name. Any
 * failure, including the timeout below, falls back to `undefined`, same as
 * an unresolved token, showing the placeholder glyph instead.
 */
async function fetchTwitchAvatar(login: string): Promise<string | undefined> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), AVATAR_FETCH_TIMEOUT_MS);
  try {
    const res = await fetch(
      `${AVATAR_LOOKUP_URL}?login=${encodeURIComponent(login)}`,
      {
        signal: controller.signal,
        headers: { Authorization: `Bearer ${API_TOKEN}` },
      },
    );
    if (!res.ok) {
      return undefined;
    }
    const data = (await res.json()) as AvatarLookupResponse;
    return data.avatarUrl ?? undefined;
  } catch {
    return undefined;
  } finally {
    clearTimeout(timeout);
  }
}

const MAX_WAIT_MS = 3000;
const POLL_INTERVAL_MS = 100;

/**
 * The second token (besides `{name}`) each type's display actually depends
 * on, so `render()` knows to wait for it too.
 */
const NUMERIC_TOKEN: Partial<Record<StreamlabsAlertBoxType, string>> = {
  resub: "months",
  giftsub: "count",
  bits: "amount",
  raid: "count",
  tip: "amount",
};

/**
 * Streamlabs doesn't guarantee its tokens are already substituted into the
 * DOM the instant this script runs, only that they eventually are, so this
 * polls for up to `MAX_WAIT_MS`, well short of the alert's own 5s duration,
 * instead of a single read that could catch `{name}` or `NUMERIC_TOKEN` too
 * early and render with a default instead of the real value.
 */
async function render(startedAt = Date.now()): Promise<void> {
  const tokens = document.getElementById("zw-tokens");
  const boxType = tokens?.dataset.alertType as
    StreamlabsAlertBoxType | undefined;
  const root = document.getElementById("root");
  if (!tokens || !boxType || !root) {
    console.error(
      "[zw] streamlabs-alertbox.js: missing #zw-tokens[data-alert-type] or #root",
    );
    return;
  }
  const name = readName(tokens);
  // Only {name} was ever waited on, so a type whose display depends on a
  // second token (party size, months, amount...) could render before that
  // one had substituted, silently falling back to its own default.
  const numericToken = NUMERIC_TOKEN[boxType];
  const numericReady = !numericToken || readToken(tokens, numericToken) !== "";
  if ((!name || !numericReady) && Date.now() - startedAt < MAX_WAIT_MS) {
    setTimeout(() => render(startedAt), POLL_INTERVAL_MS);
    return;
  }
  if (!name || !numericReady) {
    console.warn(
      "[zw] streamlabs-alertbox.js: token(s) never resolved, using defaults",
      tokens.outerHTML,
    );
  }
  const tier = (tokens.dataset.tier as AlertTier | undefined) || "big";
  const variant = tokens.dataset.variant || undefined;
  const event = buildEvent(tokens, boxType, tier);
  if (!event.avatar && name) {
    event.avatar = await fetchTwitchAvatar(name);
  }
  const stage = new AlertStage(root, { top: TOP_OFFSET, onDone: () => {} });
  stage.show({ ...event, variant }, DURATION);
  // TEMPORARY: confirms whether a "$" is inside our own rendered DOM or
  // something else is overlaying it.
  setTimeout(() => {
    console.log("[zw] rendered root text", root.textContent);
  }, 200);
}

void render();
